INSERT INTO cities (name, slug, region, short_description, long_description, image_url, lat, lng) VALUES
('Zagreb', 'zagreb', 'Central Croatia', 'Croatia''s capital — museums, cafés, and the beloved Christmas markets.', 'A vibrant capital blending Austro-Hungarian elegance with a thriving food scene, world-class museums, and the historic Upper Town. Zagreb''s café culture along Tkalčićeva Street and its award-winning Christmas markets make it a year-round destination.', 'https://images.pexels.com/photos/27401067/pexels-photo-27401067.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 45.8150, 15.9819),
('Split', 'split', 'Dalmatia', 'A coastal jewel built inside a Roman emperor''s palace.', 'Home to Diocletian''s Palace, Split pairs ancient Roman ruins with a buzzing waterfront Riva. The gateway to the Dalmatian islands offers seafood dining, lively nightlife, and boat trips to Hvar and the Blue Cave.', 'https://images.pexels.com/photos/18759975/pexels-photo-18759975.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 43.5081, 16.4402),
('Dubrovnik', 'dubrovnik', 'Dalmatia', 'The Pearl of the Adriatic — medieval walls above the sea.', 'Encircled by massive stone walls, Dubrovnik''s marble Old Town is a UNESCO wonder. Walk the city walls, ride the cable car, sail to the Elaphiti Islands, and dine where Game of Thrones was filmed.', 'https://images.pexels.com/photos/15552997/pexels-photo-15552997.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 42.6507, 18.0944),
('Zadar', 'zadar', 'Dalmatia', 'Roman ruins, the Sea Organ, and the most beautiful sunset in the world.', 'Zadar mixes Roman forums and Venetian gates with modern art: the Sea Organ plays with the waves and the Greeting to the Sun glows after dark. Nearby, Krka National Park and Paklenica await.', 'https://images.pexels.com/photos/17268879/pexels-photo-17268879.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 44.1194, 15.2314),
('Rovinj', 'rovinj', 'Istria', 'A romantic Istrian fishing town tumbling down to the sea.', 'Cobbled streets wind past pastel houses to the Church of St. Euphemia''s bell tower. Rovinj blends Italian flair with Croatian charm, surrounded by pine forests, islands, and top spas.', 'https://images.pexels.com/photos/33676833/pexels-photo-33676833.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 45.0817, 13.6386),
('Pula', 'pula', 'Istria', 'A Roman amphitheatre rising above the Adriatic.', 'Pula''s 2,000-year-old arena still hosts concerts beneath the stars. Roman temples, a working port, and the nearby Brijuni islands make it a unique Istrian stop.', 'https://images.pexels.com/photos/12337657/pexels-photo-12337657.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 44.8666, 13.8496),
('Šibenik', 'sibenik', 'Dalmatia', 'A fortress city between two national parks.', 'Šibenik''s UNESCO-listed St. James Cathedral is carved entirely from stone. Fortresses crown the hills, Krka waterfalls lie inland, and the Kornati islands float offshore.', 'https://images.pexels.com/photos/17563088/pexels-photo-17563088.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 43.7350, 15.8954),
('Varaždin', 'varazdin', 'Northern Croatia', 'Croatia''s baroque capital of music and gardens.', 'Once the capital of Croatia, Varaždin is a city of pastel façades, baroque churches, and the romantic Old Town Castle. Its annual Špancirfest fills the streets with music and art.', 'https://images.pexels.com/photos/40102376/pexels-photo-40102376.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 46.3056, 16.3366),
('Rijeka', 'rijeka', 'Kvarner', 'A bustling port city crowned by Trsat Castle.', 'European Capital of Culture 2020, Rijeka blends industrial heritage with seaside charm. Climb to Trsat Castle, explore the old port, and reach nearby Opatija and the Kvarner islands.', 'https://images.pexels.com/photos/29674356/pexels-photo-29674356.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 45.3271, 14.4422),
('Osijek', 'osijek', 'Slavonia', 'Slavonia''s gracious river city on the Drava.', 'Osijek''s Tvrđa old town is a baroque gem, and the Drava riverfront invites long walks. It''s the gateway to Slavonian wine country, Kopački Rit wetlands, and hearty local cuisine.', 'https://images.pexels.com/photos/11998729/pexels-photo-11998729.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 45.5550, 18.6955),
('Hvar', 'hvar', 'Dalmatia', 'The sunniest island — lavender, yachts, and hidden coves.', 'Hvar Town is a glamorous harbor of Venetian palaces and beach clubs. Inland, lavender fields and old stone villages lead to the Pakleni islets for swimming and sailing.', 'https://images.pexels.com/photos/13736149/pexels-photo-13736149.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 43.1729, 16.4414),
('Korčula', 'korcula', 'Dalmatia', 'A green island of wine, walls, and Marco Polo.', 'Korčula Town is a fish-bone-laid medieval city, birthplace of Marco Polo. Surrounded by vineyards of Pošip and Grk, it''s a wine lover''s island with quiet coves and sailboat days.', 'https://images.pexels.com/photos/35695148/pexels-photo-35695148.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 42.9556, 17.1367),
('Trogir', 'trogir', 'Dalmatia', 'A tiny UNESCO island-town of carved stone.', 'Trogir is a perfectly preserved medieval town on an islet, its St. Lawrence Cathedral a masterpiece of Romanesque and Renaissance carving. A short hop from Split, it''s a quiet gem.', 'https://images.pexels.com/photos/37762125/pexels-photo-37762125.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 43.5165, 16.2502),
('Makarska', 'makarska', 'Dalmatia', 'Beaches beneath the Biokovo mountains.', 'Makarska sits on a sweep of pebble beach backed by the dramatic Biokovo range. It''s the gateway to Paklenica climbing, Biokovo Nature Park, and island-hopping to Brač and Hvar.', 'https://images.pexels.com/photos/34592239/pexels-photo-34592239.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 43.2994, 17.0181),
('Cavtat', 'cavtat', 'Dalmatia', 'A serene Riviera town just south of Dubrovnik.', 'Cavtat wraps around a pine-scented bay with a palm-lined promenade. Quiet cafés, Renaissance palaces, and boat trips to Dubrovnik and the Elaphiti islands make it a relaxed alternative to the big city.', 'https://images.pexels.com/photos/16907777/pexels-photo-16907777.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 42.5809, 18.2192),
('Opatija', 'opatija', 'Kvarner', 'The grand dame of the Adriatic Riviera.', 'Opatija was the Habsburgs'' favorite seaside resort, and its villas, grand hotels, and 12 km Lungomare promenade still shimmer. Today it''s Croatia''s wellness capital with top spas and gastronomy.', 'https://images.pexels.com/photos/17624950/pexels-photo-17624950.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 45.3386, 14.3050),
('Poreč', 'porec', 'Istria', 'Byzantine mosaics and a lively Istrian Riviera.', 'Poreč''s Euphrasian Basilica glows with 6th-century mosaics, a UNESCO treasure. The old town, marina, and beaches make it a family favorite, with truffle and wine country inland.', 'https://images.pexels.com/photos/27507354/pexels-photo-27507354.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 45.2292, 13.5936),
('Motovun', 'motovun', 'Istria', 'A hilltop town in the heart of truffle country.', 'Motovun rises above the Mirna valley, its medieval walls looking over truffle forests and vineyards. It''s the soul of Istrian gastronomy — truffle hunts, Malvazija wine, and the famous film festival.', 'https://images.pexels.com/photos/33395200/pexels-photo-33395200.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 45.3375, 13.8289),
('Vis', 'vis', 'Dalmatia', 'Croatia''s most remote island — untouched and pristine.', 'Once a Yugoslav military base, Vis stayed hidden for decades. Now its hidden bays (like Stiniva), Blue Cave on Biševo, and slow-paced fishing villages draw sailors and food lovers alike.', 'https://images.pexels.com/photos/12897941/pexels-photo-12897941.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 43.0628, 16.1817),
('Ston', 'ston', 'Dalmatia', 'Salt pans, oysters, and Europe''s Great Wall.', 'Ston guards the entrance to the Pelješac peninsula with 5 km of medieval walls — the longest in Europe. Its 2,000-year-old salt pans and Mali Ston oyster farms make it a foodie pilgrimage.', 'https://images.pexels.com/photos/19152528/pexels-photo-19152528.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', 42.8456, 17.6986)
